/* hd-fonts.js - ฟอนต์ Kanit (400/500/600) ฝังในไฟล์ ใช้ได้ออฟไลน์ (SIL Open Font License 1.1 · Cadson Demak)
   subset เฉพาะไทย ละติน เครื่องหมายวรรคตอน ลูกศร และสัญลักษณ์ที่ใช้ในแอป (~87 KB)
   กติกาบ้าน: HTML และสไลด์ใช้ Kanit · TH Sarabun New ใช้เฉพาะไฟล์ Word ที่ส่งออกเท่านั้น
   ไฟล์นี้ฉีด @font-face เข้า <head> ให้เอง และเก็บสตริงไว้ที่ window.HD_FONTCSS สำหรับหน้าพิมพ์/PDF ที่เปิดหน้าต่างใหม่ */
window.HD_FONTCSS="@font-face{font-family:'Kanit';font-style:normal;font-weight:400;font-display:swap;src:local('Kanit Regular'),local('Kanit-Regular'),url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Kanit';font-style:normal;font-weight:500;font-display:swap;src:local('Kanit Medium'),local('Kanit-Medium'),url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Kanit';font-style:normal;font-weight:600 800;font-display:swap;src:local('Kanit SemiBold'),local('Kanit-SemiBold'),url(data:font/woff2;base64,) format('woff2')}";
(function(){if(typeof document==="undefined"||document.getElementById("hd-fonts"))return;const s=document.createElement("style");s.id="hd-fonts";s.textContent=window.HD_FONTCSS;(document.head||document.documentElement).appendChild(s)})();
